/// Error enum for LambdaCore
public struct LambdaCoreErrorType: AWSErrorType, Decodable {
    @nonexhaustive
    public enum Code: Sendable {
        /// One of the parameters in the request is not valid. Check the error message for details about which parameter failed validation.
        case invalidParameterValueException(LambdaCore.InvalidParameterValueException)
        /// The account has reached the maximum number of network connectors allowed. Delete unused connectors or request a limit increase through Service Quotas.
        case networkConnectorLimitExceededException(LambdaCore.NetworkConnectorLimitExceededException)
        /// The request could not be completed due to a conflict with the current state of the resource. For example, attempting to update a connector that is not in ACTIVE state.
        case resourceConflictException(LambdaCore.ResourceConflictException)
        /// The specified network connector does not exist. Verify the identifier (ID, name, or ARN) and Region.
        case resourceNotFoundException(LambdaCore.ResourceNotFoundException)
        /// An internal service error occurred. Retry the request with exponential backoff.
        case serviceException(LambdaCore.ServiceException)
        /// The request was throttled due to exceeding the allowed request rate. Retry the request after a brief wait using exponential backoff.
        case tooManyRequestsException(LambdaCore.TooManyRequestsException)
    }

    public let error: Code
    public let message: String?
    public let response: HTTPResponse?

    public init(from decoder: any Decoder) throws {
        let singleValueContainer = try decoder.singleValueContainer()
        let responseError = try singleValueContainer.decode(AWSResponseError.self)
        switch responseError.errorCode {
        case "InvalidParameterValueException":
            let context = try singleValueContainer.decode(LambdaCore.InvalidParameterValueException.self)
            self.error = .invalidParameterValueException(context)
        case "NetworkConnectorLimitExceededException":
            let context = try singleValueContainer.decode(LambdaCore.NetworkConnectorLimitExceededException.self)
            self.error = .networkConnectorLimitExceededException(context)
        case "ResourceConflictException":
            let context = try singleValueContainer.decode(LambdaCore.ResourceConflictException.self)
            self.error = .resourceConflictException(context)
        case "ResourceNotFoundException":
            let context = try singleValueContainer.decode(LambdaCore.ResourceNotFoundException.self)
            self.error = .resourceNotFoundException(context)
        case "ServiceException":
            let context = try singleValueContainer.decode(LambdaCore.ServiceException.self)
            self.error = .serviceException(context)
        case "TooManyRequestsException":
            let context = try singleValueContainer.decode(LambdaCore.TooManyRequestsException.self)
            self.error = .tooManyRequestsException(context)
        default:
            throw responseError
        }
        self.message = responseError.message
        self.response = responseError.response
    }

    /// return error code string
    public var errorCode: String {
        switch error {
        case .invalidParameterValueException: "InvalidParameterValueException"
        case .networkConnectorLimitExceededException: "NetworkConnectorLimitExceededException"
        case .resourceConflictException: "ResourceConflictException"
        case .resourceNotFoundException: "ResourceNotFoundException"
        case .serviceException: "ServiceException"
        case .tooManyRequestsException: "TooManyRequestsException"
        }
    }
}
